sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
  try {
    var result;
    var __result = (function() {
      var APP='9c6ed2452b2c93d0b7b1f93a5e91bfa9';
      gs.setCurrentApplicationId(APP);
      var out=[];
      out.push('current app: '+gs.getCurrentApplicationId());
      function mkTable(name,label,sup,extensible){
        var t=new GlideRecord('sys_db_object');
        if(t.get('name',name)){return 'exists '+name;}
        t.initialize();
        t.name=name; t.label=label;
        if(sup){var s=new GlideRecord('sys_db_object'); s.get('name',sup); t.super_class=s.sys_id;}
        t.is_extendable=!!extensible;
        t.create_access_controls=true;
        t.sys_scope=APP;
        var id=t.insert();
        return name+' -> '+id;
      }
      out.push(mkTable('x_snc_red_folder_type','Red Folder Type',null,false));
      out.push(mkTable('x_snc_red_folder_route','Red Folder Routing Rule',null,false));
      out.push(mkTable('x_snc_red_folder_folder','Red Folder','task',true));
      var chk=new GlideRecord('sys_db_object');chk.addQuery('name','STARTSWITH','x_snc_red_folder');chk.query();
      while(chk.next()){out.push(chk.name+' scope='+chk.sys_scope.getDisplayValue()+' super='+chk.super_class.getDisplayValue());}
      var g=new GlideRecord('x_snc_red_folder_folder'); out.push('folder table valid: '+g.isValid());
      out.join('\n');
      ; if (typeof result !== 'undefined') return result;
    })();
    response.setBody({ success: true, result: (__result === undefined ? null : __result) });
  } catch(e) {
    response.setBody({ success: false, error: e + '', message: e.message || (e + '') });
  }
})(request, response);
